import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class DefaultKeyedValues_removeValue_TriageGen0Test {

    private DefaultKeyedValues keyedValues;

    @Before
    public void setUp() {
        keyedValues = new DefaultKeyedValues();
    }

    /**
     * Tests removing a value that exists in the collection.
     * This covers the standard successful path.
     */
    @Test
    public void testRemoveValue_Success() {
        String key1 = "A";
        String key2 = "B";
        double val1 = 10.0;
        double val2 = 20.0;

        keyedValues.addValue(key1, val1);
        keyedValues.addValue(key2, val2);

        assertEquals(2, keyedValues.getItemCount());

        // Remove existing key
        keyedValues.removeValue(key1);

        assertEquals(1, keyedValues.getItemCount());
        assertEquals(key2, keyedValues.getKey(0));
        assertEquals(val2, keyedValues.getValue(0).doubleValue(), 0.001);
    }

    /**
     * Tests removing a value that does not exist.
     * Based on the provided implementation, if getIndex(key) returns -1, 
     * it calls removeValue(-1). 
     * This test ensures the behavior of the underlying removeValue(int) is triggered.
     */
    @Test(expected = IndexOutOfBoundsException.class)
    public void testRemoveValue_NonExistentKey() {
        keyedValues.addValue("A", 1.0);

        // getIndex("B") will likely return -1
        // removeValue(-1) should throw IndexOutOfBoundsException
        keyedValues.removeValue("B");
    }

    /**
     * Tests removing a value from an empty collection.
     */
    @Test(expected = IndexOutOfBoundsException.class)
    public void testRemoveValue_EmptyCollection() {
        keyedValues.removeValue("AnyKey");
    }

    /**
     * Tests the logic for a key that is null (if the implementation allows).
     */
    @Test(expected = IndexOutOfBoundsException.class)
    public void testRemoveValue_NullKey() {
        keyedValues.addValue("A", 1.0);
        keyedValues.removeValue(null);
    }
}
